import json, hashlib, re
from pathlib import Path

repo=Path("/Users/steventran/do-again")
key=hashlib.sha256(str(repo.resolve()).encode()).hexdigest()[:12]
root=Path.home()/".do_again/projects"/key
state=root/"state"
control=root/"control"

def read_json(p):
    try:
        v=json.loads(p.read_text())
        return v if isinstance(v,dict) else {}
    except Exception:
        return {}

def names(d):
    return sorted(p.stem for p in d.glob("*.json")) if d.is_dir() else []

cfg=(repo/"do-again.toml").read_text()
m=re.search(r"(?m)^\s*recovery_seconds\s*=\s*(\d+)\s*$",cfg)
recovery=int(m.group(1)) if m else 900

liveness=read_json(state/"liveness.json")
browser=read_json(state/"browser_status.json")
outbox=names(state/"browser_outbox")
requests=names(control/"automation/do_again/requests")
receipts=set(names(control/"automation/do_again/receipts"))
pending=[r for r in requests if r not in receipts]

incidents=[]
for d in [state/"incidents", state/"runtime_incidents"]:
    if d.is_dir():
        for p in sorted(d.glob("*.json")):
            incidents.append({"path":str(p),"value":read_json(p)})

print(json.dumps({
  "recovery_seconds":recovery,
  "liveness":liveness,
  "browser_status":browser,
  "outbox_ids":outbox,
  "pending_requests":pending,
  "incidents":incidents[-20:],
},indent=2,sort_keys=True))

if liveness.get("goal_id")!="issue-10-live-ci-handoff-proof":
    raise SystemExit("unexpected goal id")
if liveness.get("goal_state")!="waiting_for_execution":
    raise SystemExit("goal did not durably transition to waiting_for_execution")
if liveness.get("ci_terminal_fingerprint")!="Tran-Steven/do-again:37723478310:65f9a3e792c3cf3fa951df21fe9114a180d85d40:success":
    raise SystemExit("terminal CI fingerprint missing/changed")
if browser.get("state")!="ready":
    raise SystemExit("browser not recovered")
if outbox:
    raise SystemExit(f"unexpected browser outbox backlog: {outbox}")
if any("selfdev-live-ci-handoff-proof-20261007-101" in x for x in pending):
    raise SystemExit("original CI proof request is pending/replayed")
print("LIVE_CI_HANDOFF_ACCEPTANCE_OK")
